for(const [id,pic] of Object.entries(nagoyaPhotoQa)){
 if(id==='1017'||id==='3413')continue;
 const place=samples.find(p=>String(p.id)===id);if(!place)continue;
 const previous=photoForPlace(place),replacement={...pic,alt:place.name};
 if(pic.width/pic.height<.8){replacement.fit='contain';photoQaContain.add(pic.src)}
 tokyoPhotos[id]=replacement;
 for(const [key,hero] of Object.entries(designPhotos))if(previous?.src&&hero.src===previous.src&&[place.pref,place.area,place.town,place.name].includes(key))designPhotos[key]={...replacement};
 for(const r of regionalCatalog){if(r.pref===place.pref&&r.photos?.[id])r.photos[id]={...replacement};if(r.pref===place.pref&&previous?.src&&r.hero?.src===previous.src)r.hero={...replacement}}
 const host=document.querySelector('#photoCreditList'),row=document.createElement('p'),link=document.createElement('a');row.className='photoAttribution';row.setAttribute('translate','no');link.href=pic.source;link.target='_blank';link.rel='noopener';link.textContent=pic.filename;row.append(link,document.createTextNode(' · '+pic.author+' · '+pic.license+' · WebP / resized'));host.append(row);
}

